  const g: number = 1.15
  const c: number = 0.18
  const c_d: number = 10.013
  const w_g: number = 0.14
  const t_1: number = 0.04
  const r_hit_min: number = 128
  const r_hit_max: number = 896

  const r_hit: number =
    r_hit_min + (r_hit_max - r_hit_min) * (Math.log(n / n_r) / Math.log(10000 / 100))
  const m_0: number = n / n_r
  const m_1: number = 0.5 * (m_0 + Math.sqrt(m_0 * (m_0 + 4 * t_1)))
  const u: number = Math.pow(r_hit / m_1 / (r_hit / m_1 + 1), g)
  const m: number = m_1 / u
  const w_i: number = Math.log(n / 100) / Math.log(2)
  const c_t: number = (c_d / n_r) * (1 + w_i * w_g)
  const g_ip: number = 0.5 * (c_t + Math.sqrt(c_t * (c_t + 4 * t_1)))
  const g_ipp2: number = -(m_1 * Math.pow(g_ip / m, 1 / g)) / (Math.pow(g_ip / m, 1 / g) - 1)
  const w_2: number = c / g_ipp2
  const s_2: number = w_2 * m_1
  const u_2: number = Math.pow(r_hit / m_1 / (r_hit / m_1 + w_2), g)
  const m_2: number = m_1 / u_2

  let p: TSParams = newTSParams()
  p.n = n
  p.n_r = n_r
  p.g = g
  p.t_1 = t_1
  p.c_t = c_t
  p.s_2 = s_2
  p.u_2 = u_2
  p.m_2 = m_2
