export function Aab_to_JMh(Aab: number[], p: JMhParams): number[] {
  let JMh: number[] = acesVec(0, 0, 0)
  if (Aab[0] <= 0) {
    return JMh
  }
  let J: number = Achromatic_n_to_J(Aab[0], p.cz)
  let M: number = Math.sqrt(Aab[1] * Aab[1] + Aab[2] * Aab[2])
  let h_rad: number = Math.atan2(Aab[2], Aab[1])
  let h: number = wrap_to_360(radians_to_degrees(h_rad))

  JMh[0] = J
  JMh[1] = M
  JMh[2] = h

  return JMh
}
